const d = JSON.parse(query);
const B = 'Instagram-Leads';
const T = 'leads';
const K = 'patJqHEOkCGDZjMgJ.21b9974a5b60cc28d9ad1370c2b2d03d160c525311d421ecd11e7865433a720a';
const authHdr = { Authorization: 'Bearer ' + K };
const jsonHdr = { 'Content-Type': 'application/json', Authorization: 'Bearer ' + K };
const formula = encodeURIComponent('{instagram_handle}="' + d.instagram_handle + '"');
const sr = await fetch('https://api.airtable.com/v0/' + B + '/' + T + '?filterByFormula=' + formula + '&maxRecords=1', { headers: authHdr });
const sd = await sr.json();
const ex = sd.records && sd.records[0];
const fields = {
  instagram_handle: d.instagram_handle,
  subscriber_id: d.subscriber_id || '',
  intent: d.intent || 'other',
  status: d.status || 'new',
  contact_count: typeof d.contact_count === 'number' ? d.contact_count : 1,
  is_vip: !!d.is_vip,
  last_contact_at: new Date().toISOString(),
  notes: d.notes || ''
};
if (!ex) {
  fields.last_post_context = d.post_context || '';
}
const method = ex ? 'PATCH' : 'POST';
const url = ex ? 'https://api.airtable.com/v0/' + B + '/' + T + '/' + ex.id : 'https://api.airtable.com/v0/' + B + '/' + T;
const body = ex ? { fields: fields } : { records: [{ fields: fields }] };
const wr = await fetch(url, { method: method, headers: jsonHdr, body: JSON.stringify(body) });
return ex ? '업데이트 완료: ' + d.instagram_handle : '신규 저장 완료: ' + d.instagram_handle;

